1	//! Explicit profile 3: a recipe-bound copy, followed by current-issuer admission.
2	//! This owner API does not activate a service or fence another physical copy.
3	use super::copy_upgrade::{frame, PlannedCopy, SOURCE_DOMAIN};
4	use super::*;
5	use crate::{
6	    evidence_attestation::{self as proof, Purpose},
7	    evidence_copy_plan::Plan,
8	    evidence_service::{Failure, Grant},
9	    sign::Identity,
10	};
11	
12	pub(crate) const SCHEMA: &str = "
13	CREATE TABLE upgrade_plan(
14	 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
15	 envelope BLOB NOT NULL CHECK(length(envelope)>0 AND length(envelope)<=4096));
16	CREATE TABLE upgrade_objects(
17	 cid TEXT PRIMARY KEY,
18	 length INTEGER NOT NULL CHECK(length>=1 AND length<=4194304)) WITHOUT ROWID;
19	PRAGMA user_version=3;
20	";
21	
22	#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
23	pub struct Status {
24	    pub original_objects: u64,
25	    pub copied_records: u64,
26	    pub planned_records: u64,
27	    pub source_copy_complete: bool,
28	}
29	#[derive(Debug)]
30	pub struct Verification {
31	    pub contents: super::Verification,
32	    pub copy: Status,
33	}
34	#[derive(Debug, Clone, Copy)]
35	pub struct Budget {
36	    pub objects: usize,
37	    pub records: usize,
38	    pub bytes: usize,
39	}
40	impl Budget {
41	    pub fn validate(self) -> Result<()> {
42	        if self.objects > 4096
43	            || self.records > 4096
44	            || (self.objects == 0 && self.records == 0)
45	            || !(MAX_CHUNK..=64 * 1024 * 1024).contains(&self.bytes)
46	        {
47	            return Err(Error::Invalid("copy budget"));
48	        }
49	        Ok(())
50	    }
51	}
52	#[derive(Debug)]
53	pub struct Batch {
54	    pub status: Status,
55	    pub objects_written: usize,
56	    pub records_written: usize,
57	    pub bytes_written: usize,
58	}
59	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
60	pub enum CopyBoundary {
61	    ObjectInserted,
62	    InventoryInserted,
63	    ManifestInserted,
64	    ProofSigned,
65	    ProofInserted,
66	    BeforeCommit,
67	    AfterCommit,
68	}
69	
70	fn corrupt(message: &str) -> Error {
71	    Error::Corrupt(message.into())
72	}
73	fn configured(binding: &attested::Binding, plan: &Plan) -> Result<()> {
74	    binding.validate()?;
75	    plan.check_archive(&binding.archive)?;
76	    if plan.target().scope != binding.scope || plan.target().issuer != binding.issuer {
77	        return Err(Error::Invalid("copy plan differs from owner binding"));
78	    }
79	    Ok(())
80	}
81	fn stored_plan(conn: &Connection, binding: &attested::Binding) -> Result<Plan> {
82	    let count: i64 = conn.query_row("SELECT count(*) FROM upgrade_plan", [], |r| r.get(0))?;
83	    let (length, bytes): (i64, Vec<u8>) = conn.query_row(
84	        "SELECT length(envelope),substr(envelope,1,4096) FROM upgrade_plan WHERE singleton=1",
85	        [],
86	        |r| Ok((r.get(0)?, r.get(1)?)),
87	    )?;
88	    if count != 1 || !(1..=4096).contains(&length) || length as usize != bytes.len() {
89	        return Err(corrupt("copy plan cardinality or length"));
90	    }
91	    let plan = Plan::decode(&bytes)?;
92	    configured(binding, &plan)?;
93	    attested::check_binding(conn, binding)?;
94	    Ok(plan)
95	}
96	pub(super) fn check_plan(
97	    conn: &Connection,
98	    binding: &attested::Binding,
99	    plan: &Plan,
100	) -> Result<()> {
101	    configured(binding, plan)?;
102	    if stored_plan(conn, binding)?.bytes() != plan.bytes() {
103	        return Err(corrupt("stored copy plan changed"));
104	    }
105	    Ok(())
106	}
107	pub(super) fn initialize(
108	    tx: &rusqlite::Transaction<'_>,
109	    binding: &attested::Binding,
110	    plan: &Plan,
111	) -> Result<()> {
112	    configured(binding, plan)?;
113	    // surface-write: evidence-copy-sqlite:upgrade_plan,evidence-copy-sqlite:upgrade_objects
114	    crate::persistence::initialize_evidence_copy(
115	        crate::persistence::SurfaceWrite::EvidenceCopy,
116	        tx,
117	        plan.bytes(),
118	    )?;
119	    Ok(())
120	}
121	
122	// Caller owns a pinned transaction and has fully verified payloads/base metadata.
123	// Partial source-copy status is not proof that a prefix matches an unavailable
124	// source; resumption additionally compares it against the audited PlannedCopy.
125	pub(super) fn audit(
126	    ledger: &Ledger,
127	    binding: &attested::Binding,
128	    plan: &Plan,
129	    base: &super::Verification,
130	) -> Result<Status> {
131	    ledger.check_profile(3)?;
132	    audit_state(
133	        &ledger.conn,
134	        binding,
135	        plan,
136	        base.snapshot.through,
137	        base.objects,
138	    )
139	}
140	fn audit_state(
141	    conn: &Connection,
142	    binding: &attested::Binding,
143	    plan: &Plan,
144	    through: u64,
145	    objects: u64,
146	) -> Result<Status> {
147	    check_plan(conn, binding, plan)?;
148	    let copied_records = through.min(plan.source().through);
149	    let mut hash = Sha256::new();
150	    hash.update(SOURCE_DOMAIN);
151	    frame(&mut hash, b"commits");
152	    hash.update(plan.source().through.to_be_bytes());
153	    for sequence in 1..=copied_records {
154	        let row = attested::record(conn, sequence)?;
155	        let es: Vec<_> = entries(&row.manifest).collect();
156	        if es.len() != 1 {
157	            return Err(corrupt("copy request entry"));
158	        }
159	        let request: Cid = cid(&es[0]["ciphertext"])
160	            .parse()
161	            .map_err(|_| corrupt("copy request CID"))?;
162	        hash.update(sequence.to_be_bytes());
163	        frame(&mut hash, row.manifest.bytes());
164	        frame(&mut hash, row.receipt.bytes());
165	        frame(&mut hash, &request.to_bytes());
166	        if sequence == plan.source().through
167	            && plan.source().tip.as_ref() != Some(row.manifest.cid())
168	        {
169	            return Err(corrupt("copy source tip"));
170	        }
171	    }
172	    let count: i64 = conn.query_row("SELECT count(*) FROM upgrade_objects", [], |r| r.get(0))?;
173	    let original_objects = u64::try_from(count).map_err(|_| corrupt("copy object count"))?;
174	    frame(&mut hash, b"objects");
175	    hash.update(original_objects.to_be_bytes());
176	    let mut stmt = conn.prepare("SELECT cid,length FROM upgrade_objects ORDER BY cid")?;
177	    let mut rows = stmt.query([])?;
178	    while let Some(row) = rows.next()? {
179	        let text: String = row.get(0)?;
180	        let id: Cid = text.parse().map_err(|_| corrupt("original object CID"))?;
181	        let length: i64 = row.get(1)?;
182	        if !(1..=MAX_CHUNK as i64).contains(&length) || id.to_string() != text {
183	            return Err(corrupt("original object coordinate"));
184	        }
185	        let payload: Vec<u8> = conn
186	            .query_row(
187	                "SELECT substr(bytes,1,4194304) FROM objects WHERE cid=? AND length(bytes)=?",
188	                params![text, length],
189	                |r| r.get(0),
190	            )
191	            .optional()?
192	            .ok_or_else(|| corrupt("original object missing or length changed"))?;
193	        if payload.len() as i64 != length || ciphertext_cid(&payload) != id {
194	            return Err(corrupt("original object length"));
195	        }
196	        frame(&mut hash, &id.to_bytes());
197	        hash.update((length as u64).to_be_bytes());
198	    }
199	    let digest: [u8; 32] = hash.finalize().into();
200	    let complete = copied_records == plan.source().through && digest == plan.source().digest;
201	    if !complete && (through > plan.source().through || objects != original_objects) {
202	        return Err(corrupt("admission or untracked objects in incomplete copy"));
203	    }
204	    Ok(Status {
205	        original_objects,
206	        copied_records,
207	        planned_records: plan.source().through,
208	        source_copy_complete: complete,
209	    })
210	}
211	pub(super) fn full_audit(
212	    ledger: &Ledger,
213	    binding: &attested::Binding,
214	    plan: &Plan,
215	) -> Result<Verification> {
216	    ledger.check_profile(3)?;
217	    ledger.check_copy_schema()?;
218	    let contents = ledger.verify_contents()?;
219	    let (frontier, _) = attested::audit_prefix(
220	        &ledger.conn,
221	        binding,
222	        contents.snapshot.through,
223	        None,
224	        Some(plan),
225	    )?;
226	    if frontier.manifest != contents.snapshot.tip {
227	        return Err(corrupt("copy proof tip"));
228	    }
229	    let copy = audit(ledger, binding, plan, &contents)?;
230	    Ok(Verification { contents, copy })
231	}
