233	pub struct Archive {
234	    inner: attested::Archive,
235	}
236	impl Archive {
237	    /// The owner must retain the exact plan artifact and external binding before
238	    /// calling. The verified source is required even for empty initialization.
239	    pub fn create(root: &Path, source: &PlannedCopy, binding: attested::Binding) -> Result<Self> {
240	        Self::create_observed(root, source, binding, &mut |_| {})
241	    }
242	    pub fn create_observed(
243	        root: &Path,
244	        source: &PlannedCopy,
245	        binding: attested::Binding,
246	        observe: &mut dyn FnMut(InitializationBoundary),
247	    ) -> Result<Self> {
248	        configured(&binding, source.plan())?;
249	        let ledger = Ledger::create_with_plan(root, observe, Some(&binding), Some(source.plan()))?;
250	        Self::from_ledger(ledger, binding, source.plan().clone())
251	    }
252	    fn from_ledger(ledger: Ledger, binding: attested::Binding, plan: Plan) -> Result<Self> {
253	        ledger.conn.set_limit(
254	            rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
255	            RECOVERY_SQLITE_LENGTH_LIMIT,
256	        )?;
257	        let archive = Self {
258	            inner: attested::Archive {
259	                ledger,
260	                binding,
261	                copy: Some(plan),
262	            },
263	        };
264	        archive.verify()?;
265	        Ok(archive)
266	    }
267	    pub fn open(root: &Path, binding: attested::Binding) -> Result<Self> {
268	        binding.validate()?;
269	        let path = root.join("archive.sqlite");
270	        private_file(&path)?;
271	        let conn = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_WRITE)?;
272	        conn.set_limit(
273	            rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
274	            RECOVERY_SQLITE_LENGTH_LIMIT,
275	        )?;
276	        conn.busy_timeout(Duration::from_secs(5))?;
277	        let ledger = Ledger { conn };
278	        ledger.check_profile(3)?;
279	        ledger.check_copy_schema()?;
280	        let tx = ledger.conn.unchecked_transaction()?;
281	        let plan = stored_plan(&tx, &binding)?;
282	        full_audit(&ledger, &binding, &plan)?;
283	        tx.commit()?;
284	        configure(&ledger.conn)?;
285	        Self::from_ledger(ledger, binding, plan)
286	    }
287	    pub fn resume_initialization(
288	        root: &Path,
289	        source: &PlannedCopy,
290	        binding: attested::Binding,
291	    ) -> Result<Self> {
292	        configured(&binding, source.plan())?;
293	        let path = root.join("archive.sqlite");
294	        private_file(&path)?;
295	        let conn = Connection::open_with_flags(&path, OpenFlags::SQLITE_OPEN_READ_WRITE)?;
296	        let app: i64 = conn.query_row("PRAGMA application_id", [], |r| r.get(0))?;
297	        let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
298	        drop(conn);
299	        let result = if app == APPLICATION_ID && version == 3 {
300	            let result = Self::open(root, binding)?;
301	            if result.plan().bytes() != source.plan().bytes() {
302	                return Err(Error::Conflict("resume recipe differs"));
303	            }
304	            result
305	        } else {
306	            let ledger = Ledger::initialize_with_plan(
307	                root,
308	                &path,
309	                &mut |_| {},
310	                Some(&binding),
311	                Some(source.plan()),
312	            )?;
313	            Self::from_ledger(ledger, binding, source.plan().clone())?
314	        };
315	        std::fs::File::open(root)?.sync_all()?;
316	        std::fs::File::open(parent_directory(root))?.sync_all()?;
317	        Ok(result)
318	    }
319	    pub fn plan(&self) -> &Plan {
320	        self.inner.copy.as_ref().expect("copy constructor")
321	    }
322	    pub fn binding(&self) -> &attested::Binding {
323	        &self.inner.binding
324	    }
325	    pub fn verify(&self) -> Result<Verification> {
326	        let tx = self.inner.ledger.conn.unchecked_transaction()?;
327	        let result = full_audit(&self.inner.ledger, self.binding(), self.plan())?;
328	        tx.commit()?;
329	        Ok(result)
330	    }
331	    pub fn verify_file(path: &Path, binding: attested::Binding) -> Result<Verification> {
332	        binding.validate()?;
333	        let reader = RecoveryReader::open_profile(path, 3)?;
334	        let plan = stored_plan(&reader.ledger.conn, &binding)?;
335	        full_audit(&reader.ledger, &binding, &plan)
336	    }
337	    pub fn backup(&self, destination: &Path) -> Result<Verification> {
338	        self.backup_observed(destination, &mut |_| {})
339	    }
340	    pub fn backup_observed(
341	        &self,
342	        destination: &Path,
343	        observe: &mut dyn FnMut(BackupBoundary),
344	    ) -> Result<Verification> {
345	        let destination = self.inner.ledger.backup_copy(destination, observe)?;
346	        Self::verify_file(&destination, self.binding().clone())
347	    }
348	    pub fn admit(
349	        &mut self,
350	        bytes: &[u8],
351	        signer: &Identity,
352	        grant: &Grant,
353	        now: u64,
354	    ) -> std::result::Result<attested::Admission, Failure> {
355	        self.inner.admit(bytes, signer, grant, now)
356	    }
357	    /// Fault harness only; callbacks cannot establish durability.
358	    pub fn admit_observed(
359	        &mut self,
360	        bytes: &[u8],
361	        signer: &Identity,
362	        grant: &Grant,
363	        now: u64,
364	        observe: &mut dyn FnMut(Boundary),
365	    ) -> std::result::Result<attested::Admission, Failure> {
366	        self.inner
367	            .admit_observed(bytes, signer, grant, now, observe)
368	    }
369	    pub fn copy_batch(
370	        &mut self,
371	        source: &PlannedCopy,
372	        signer: &Identity,
373	        issued_at: u64,
374	        budget: Budget,
375	    ) -> Result<Batch> {
376	        self.copy_batch_observed(source, signer, issued_at, budget, &mut |_| {})
377	    }
378	    pub fn copy_batch_observed(
379	        &mut self,
380	        source: &PlannedCopy,
381	        signer: &Identity,
382	        issued_at: u64,
383	        budget: Budget,
384	        observe: &mut dyn FnMut(CopyBoundary),
385	    ) -> Result<Batch> {
386	        budget.validate()?;
387	        if signer.did().as_str() != self.binding().issuer
388	            || source.plan().bytes() != self.plan().bytes()
389	        {
390	            return Err(Error::Invalid("copy signer or recipe mismatch"));
391	        }
392	        let ledger = &self.inner.ledger;
393	        let tx =
394	            rusqlite::Transaction::new_unchecked(&ledger.conn, TransactionBehavior::Immediate)?;
395	        let before = full_audit(ledger, self.binding(), self.plan())?;
396	        let src = &source.reader().ledger;
397	        let mut originals = src
398	            .conn
399	            .prepare("SELECT cid,length(bytes) FROM objects ORDER BY cid")?;
400	        let mut source_rows = originals.query([])?;
401	        let mut inventory = tx.prepare("SELECT cid,length FROM upgrade_objects ORDER BY cid")?;
402	        let mut copied = inventory.query([])?;
403	        while let Some(old) = copied.next()? {
404	            let expected = source_rows
405	                .next()?
406	                .ok_or_else(|| corrupt("destination has extra original objects"))?;
407	            let id: String = old.get(0)?;
408	            let length: i64 = old.get(1)?;
409	            if id != expected.get::<_, String>(0)? || length != expected.get::<_, i64>(1)? {
410	                return Err(corrupt(
411	                    "original object inventory differs from source prefix",
412	                ));
413	            }
414	            let parsed: Cid = id.parse().map_err(|_| corrupt("original CID"))?;
415	            if ledger.read_object(&parsed)? != src.read_object(&parsed)? {
416	                return Err(corrupt("copied object bytes differ"));
417	            }
418	        }
419	        drop(copied);
420	        drop(inventory);
421	        for sequence in 1..=before.copy.copied_records {
422	            let old = attested::record(&tx, sequence)?;
423	            let expected = source.reader().record(sequence)?;
424	            if old.manifest.bytes() != expected.manifest.bytes()
425	                || old.receipt.bytes() != expected.receipt.bytes()
426	            {
427	                return Err(corrupt("copied record differs from source"));
428	            }
429	        }
430	        let mut objects_written = 0;
431	        let mut records_written = 0;
432	        let mut bytes_written = 0;
433	        let mut objects_done = true;
434	        while let Some(row) = source_rows.next()? {
435	            if before.contents.commits > 0 {
436	                return Err(corrupt("records precede complete original inventory"));
437	            }
438	            let id: String = row.get(0)?;
439	            let length: i64 = row.get(1)?;
440	            let length = usize::try_from(length).map_err(|_| corrupt("source object length"))?;
441	            if objects_written == budget.objects || length > budget.bytes - bytes_written {
442	                objects_done = false;
443	                break;
444	            }
445	            let parsed: Cid = id.parse().map_err(|_| corrupt("source object CID"))?;
446	            let bytes = src.read_object(&parsed)?;
447	            tx.execute("INSERT INTO objects VALUES(?,?)", params![id, bytes])?;
448	            observe(CopyBoundary::ObjectInserted);
449	            // surface-write: evidence-copy-sqlite:upgrade_objects
450	            crate::persistence::insert_evidence_copy_object(
451	                crate::persistence::SurfaceWrite::EvidenceCopy,
452	                &tx,
453	                &id,
454	                length as i64,
455	            )?;
456	            observe(CopyBoundary::InventoryInserted);
457	            objects_written += 1;
458	            bytes_written += length;
459	        }
460	        drop(source_rows);
461	        drop(originals);
462	        if objects_done {
463	            let (mut frontier, _) = attested::audit_prefix(
464	                &tx,
465	                self.binding(),
466	                before.contents.snapshot.through,
467	                None,
468	                Some(self.plan()),
469	            )?;
470	            for sequence in before.copy.copied_records + 1..=self.plan().source().through {
471	                if records_written == budget.records {
472	                    break;
473	                }
474	                let row = source.reader().record(sequence)?;
475	                let required = row.manifest.bytes().len()
476	                    + row.receipt.bytes().len()
477	                    + proof::MAX_ENVELOPE_BYTES;
478	                if required > budget.bytes - bytes_written {
479	                    break;
480	                }
481	                insert_record(&tx, &row)?;
482	                observe(CopyBoundary::ManifestInserted);
483	                let signed = proof::issue(
484	                    signer,
485	                    &self.binding().context(),
486	                    &row.manifest,
487	                    &row.receipt,
488	                    &frontier,
489	                    Purpose::RetainedVerified,
490	                    issued_at,
491	                )?;
492	                observe(CopyBoundary::ProofSigned);
493	                // surface-write: evidence-proof-sqlite:attestations
494	                crate::persistence::insert_evidence_proof(
495	                    crate::persistence::SurfaceWrite::EvidenceAttestation,
496	                    &tx,
497	                    sequence as i64,
498	                    signed.bytes(),
499	                )?;
500	                observe(CopyBoundary::ProofInserted);
501	                frontier = signed.frontier().clone();
502	                records_written += 1;
503	                bytes_written +=
504	                    row.manifest.bytes().len() + row.receipt.bytes().len() + signed.bytes().len();
505	            }
506	        }
507	        let status = full_audit(ledger, self.binding(), self.plan())?.copy;
508	        observe(CopyBoundary::BeforeCommit);
509	        tx.commit()?;
510	        observe(CopyBoundary::AfterCommit);
511	        Ok(Batch {
512	            status,
513	            objects_written,
514	            records_written,
515	            bytes_written,
516	        })
517	    }
518	}
519	
520	fn insert_record(tx: &rusqlite::Transaction<'_>, row: &Committed) -> Result<()> {
521	    let b = row.manifest.body();
522	    let id = row.manifest.cid().to_string();
523	    tx.execute(
524	        "INSERT INTO commits VALUES(?,?,?,?,?,?,?,?,?)",
525	        params![
526	            i64::try_from(row.sequence).map_err(|_| Error::Invalid("sequence overflow"))?,
527	            id,
528	            blob(&b["scopeToken"]),
529	            writer(&row.manifest),
530	            blob(&b["operation"]),
531	            number(&b["position"]),
532	            optional_cid(&b["previous"]),
533	            row.manifest.bytes(),
534	            row.receipt.bytes()
535	        ],
536	    )?;
537	    for e in entries(&row.manifest) {
538	        tx.execute(
539	            "INSERT INTO bindings VALUES(?,?,?,?,?,?) ON CONFLICT(scope,writer,slot) DO NOTHING",
540	            params![
541	                blob(&b["scopeToken"]),
542	                writer(&row.manifest),
543	                blob(&e["slot"]),
544	                cid(&e["ciphertext"]),
545	                number(&e["length"]),
546	                id
547	            ],
548	        )?;
549	    }
550	    Ok(())
551	}
