553	/// A pinned raw source for rebuilding derived metadata while preserving every
554	/// authoritative plan, membership, request, receipt, and proof byte.
555	pub struct Recovery {
556	    reader: RecoveryReader,
557	    binding: attested::Binding,
558	    plan: Plan,
559	}
560	impl Recovery {
