588	pub(super) fn copy_inventory(source: &Connection, tx: &rusqlite::Transaction<'_>) -> Result<()> {
589	    let mut stmt =
590	        source.prepare("SELECT cid,length FROM upgrade_objects NOT INDEXED ORDER BY cid")?;
591	    let mut rows = stmt.query([])?;
592	    while let Some(row) = rows.next()? {
593	        let text: String = row.get(0)?;
594	        let length: i64 = row.get(1)?;
595	        let id: Cid = text.parse().map_err(|_| corrupt("original object CID"))?;
596	        if id.to_string() != text || !(1..=MAX_CHUNK as i64).contains(&length) {
597	            return Err(corrupt("original object coordinate"));
598	        }
599	        // surface-write: evidence-copy-sqlite:upgrade_objects
600	        crate::persistence::insert_evidence_copy_object(
601	            crate::persistence::SurfaceWrite::EvidenceCopy,
602	            tx,
603	            &text,
604	            length,
605	        )?;
606	    }
607	    Ok(())
608	}
