610	// Re-evaluate original membership under admission's immediate writer transaction,
611	// after staging and before signing. A preflight audit alone is not a fence.
612	pub(super) fn admission_ready(
613	    conn: &Connection,
614	    binding: &attested::Binding,
615	    plan: &Plan,
616	    through: u64,
617	) -> Result<()> {
618	    let count: i64 = conn.query_row("SELECT count(*) FROM objects", [], |r| r.get(0))?;
619	    let status = audit_state(
620	        conn,
621	        binding,
622	        plan,
623	        through,
624	        u64::try_from(count).map_err(|_| corrupt("object count"))?,
625	    )?;
626	    if !status.source_copy_complete {
627	        return Err(Error::Conflict("copy is incomplete"));
