    };
    let base = |root: &Path, plan: &Path, key: &Path| -> Vec<String> {
        ["copy-batch", db.to_str().unwrap(), root.to_str().unwrap(), "--plan", plan.to_str().unwrap(), "--key", key.to_str().unwrap()].iter().map(|s| s.to_string()).collect()
    };
