        a.extend(p);
        let o = cli(&a);
        show(&format!("H {command} incomplete"), &o);
        assert!(o.status.success());
        let j: serde_json::Value = serde_json::from_slice(&o.stdout).unwrap();
        assert_eq!(j["copy"]["source_copy_complete"], false);
